    {
      "name": "Matrix.det_eval_matrixOfPolynomials_eq_det_vandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} (v : Fin n → R) (p : Fin n → Polynomial R),\n  (∀ (i : Fin n), (p i).natDegree = ↑i) →\n    (∀ (i : Fin n), (p i).Monic) → (Matrix.vandermonde v).det = (Matrix.of fun i j => Polynomial.eval (v i) (p j)).det"
    },
    {
      "name": "Matrix.det_vandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} (v : Fin n → R),\n  (Matrix.vandermonde v).det = ∏ i, ∏ j ∈ Finset.Ioi i, (v j - v i)"
    },
    {
      "name": "Matrix.det_projVandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} (v w : Fin n → R),\n  (Matrix.projVandermonde v w).det = ∏ i, ∏ j ∈ Finset.Ioi i, (v j * w i - v i * w j)"
    },
    {
      "name": "eval_det",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {n : Type w} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type u_3} [inst_2 : CommRing R]\n  (M : Matrix n n (Polynomial R)) (r : R),\n  Polynomial.eval r M.det = (Polynomial.eval ((Matrix.scalar n) r) (matPolyEquiv M)).det"
    },
    {
      "name": "Matrix.det_matrixOfPolynomials",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Block",
      "kind": "theorem",
      "type": "∀ {R : Type v} [inst : CommRing R] {n : ℕ} (p : Fin n → Polynomial R),\n  (∀ (i : Fin n), (p i).natDegree = ↑i) → (∀ (i : Fin n), (p i).Monic) → (Matrix.of fun i j => (p j).coeff ↑i).det = 1"
    }
  ]
}

